                let built = self.run_argv(build)?;
                if built.exit_code != Some(0) {
                    return Err(GraphError::ReleaseCommand {
                        program: build.program.clone(),
                        args: build.args.clone(),
                        failure: CommandFailure::NonZeroExit {
                            exit_code: built.exit_code,
                            stderr: built.stderr,
                        },
                    });
                }
