 401	fn resolve_release_profile(raw: RawReleaseProfile) -> Result<ReleaseProfile, ConfigError> {
 402	    validate_profile_name(&raw.name)?;
 403	    let forge_repository = raw.forge_repository.trim();
 404	    if forge_repository.is_empty()
 405	        || forge_repository.contains(char::is_whitespace)
 406	        || (forge_repository.contains('/') && forge_repository.split('/').count() != 2)
 407	    {
 408	        return Err(ConfigError::InvalidReleaseProfileName { name: raw.name });
 409	    }
 410	
 411	    let mut registries = BTreeMap::new();
 412	    for registry in raw.registry {
 413	        let key = RegistryKey(registry.key.clone());
 414	        let endpoint = normalize_release_endpoint(&raw.name, &registry.key, &registry.endpoint)?;
 415	        if registries.insert(key, endpoint).is_some() {
 416	            return Err(ConfigError::DuplicateReleaseProfileRegistry {
 417	                profile: raw.name,
 418	                registry: registry.key,
 419	            });
 420	        }
 421	    }
