   458	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
   459	/// [`RegistryError`].
   460	///
   461	/// Priority order (highest wins):
   462	/// 1. `"already exist"` (from `--skip-existing`) without `"uploading"` ->
   463	///    [`PublishOutcome::AlreadyPublished`] (all artifacts skipped). Both
   464	///    phrases present means at least one artifact was freshly uploaded ->
   465	///    `Published`. Handles `dist/` accumulating stale pre-release
   466	///    artifacts: `dist/my_pkg-1.0.0*` matches both `my_pkg-1.0.0a0.whl`
   467	///    (skipped) and `my_pkg-1.0.0.whl` (uploaded), producing mixed output.
   468	/// 2. Zero exit code with no skip-only mention -> [`PublishOutcome::Published`].
   469	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) ->
   470	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
   471	///    retry-after duration.
   472	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) ->
   473	///    [`RegistryError::AuthFailed`].
   474	/// 5. Anything else -> [`RegistryError::Other`].
   475	pub(crate) fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
   476	    let combined = combined_lower(output);
   477	
   478	    let has_skip = combined.contains("already exist");
   479	    let has_upload = combined.contains("uploading");
   480	    if has_skip && !has_upload {
   481	        return Ok(PublishOutcome::AlreadyPublished);
   482	    }
   483	    if output.success() {
   484	        return Ok(PublishOutcome::Published);
   485	    }
   486	    if let Some(err) = detect_rate_limit(&combined) {
   487	        return Err(err);
   488	    }
   489	    if let Some(err) = detect_auth_failure(&combined, output) {
   490	        return Err(err);
   491	    }
   492	    Err(RegistryError::Other(format!(
   493	        "twine upload failed (exit {:?}): {}",
   494	        output.exit_code,
   495	        output.redacted_stderr().trim()
   496	    )))
   497	}
